+/**
+ * @test
+ * @bug 8397474
+ * @summary C2 corrupts Arrays.copyOf results with compact object headers
+ * @run main/othervm -Xbatch -XX:+UseCompactObjectHeaders
+ *                   -XX:CompileCommand=compileonly,compiler.arraycopy.TestCopyOfGrowZeroShrink::test
+ *                   compiler.arraycopy.TestCopyOfGrowZeroShrink
+ * @run main/othervm -Xbatch -XX:-UseCompactObjectHeaders
+ *                   -XX:CompileCommand=compileonly,compiler.arraycopy.TestCopyOfGrowZeroShrink::test
+ *                   compiler.arraycopy.TestCopyOfGrowZeroShrink
+ */
+
+package compiler.arraycopy;
+
+import java.util.Arrays;
+
+public class TestCopyOfGrowZeroShrink {
+    static byte[] SRC = new byte[32];
+    static int END = 33;
+
+    static {
+        for (int i = 0; i < SRC.length; i++) SRC[i] = (byte) (i + 1);
+    }
+
+    static long test() {
+        byte[] b = Arrays.copyOf(SRC, 33);
+        for (int i = 32; i < END; i++) b[i] = 0;
+        byte[] c = Arrays.copyOf(b, 32);
+        long first8 = 0;
+        for (int i = 0; i < c.length; i++) if (i < 8) first8 |= (c[i] & 0xffL) << (8 * i);
+        return first8;
+    }
+
+    static String bytes(long x) {
+        StringBuilder sb = new StringBuilder("[");
+        for (int i = 0; i < 8; i++) sb.append(i == 0 ? "" : ", ").append((byte) (x >>> (8 * i)));
+        return sb.append(", ...]").toString();
+    }
+
+    public static void main(String[] args) {
+        long expected = test();
+        for (int iter = 1; iter < 100_000; iter++) {
+            long got = test();
+            if (got != expected) {
+                throw new RuntimeException("FAIL at iteration " + iter + ": expected "
+                        + bytes(expected) + " got " + bytes(got));
+            }
+        }
+    }
+}
